const LUMA = `vec4 pixel(vec2 uv){
  vec4 c = texture(u_src, uv);
  float l = dot(c.rgb, vec3(0.299, 0.587, 0.114));
  float a = smoothstep(l - 0.12, l + 0.12, u_prog * 1.3 - 0.15);
  return vec4(c.rgb * c.a * a, c.a * a);
}`;
// luma key for remove_background output (subject on black): alpha from brightness, so the cut-out can sit above "text behind object"
const KEY = `vec4 pixel(vec2 uv){
  vec4 c = texture(u_src, uv);
  float a = smoothstep(0.04, 0.12, max(c.r, max(c.g, c.b)));
  return vec4(c.rgb * a, a);
}`;
// light leak (GLSL, used once on the reveal): warm moving blobs, screen-blended
const LEAK = `vec4 pixel(vec2 uv){
  float t = u_time * 0.6;
  vec2 p1 = vec2(0.15 + 0.25 * sin(t), 0.25 + 0.1 * cos(t * 1.3));
  vec2 p2 = vec2(0.85 - 0.2 * cos(t * 0.8), 0.7 + 0.12 * sin(t));
  float a = exp(-8.0 * distance(uv, p1)) + 0.8 * exp(-7.0 * distance(uv, p2));
  vec3 col = mix(vec3(1.0, 0.55, 0.2), vec3(1.0, 0.82, 0.45), uv.y);
  float o = clamp(a, 0.0, 1.0) * u_amt;
  return vec4(col * o, o);
}`;

